#!/bin/sh
# Code generated by AI (Claude Code)

# Checks sudo allows a command, asking the password at most once per script.
#
# Globals:
#   sudo_refused (set)
#
# Arguments:
#   $@  Command and its arguments, an executable and not a shell function.
#
# Returns:
#   1 when sudo is missing, the password prompt failed earlier in this script, or sudoers refuses the command.
sudo_allowed() {
  [ "$(id -u)" -ne 0 ] || return 0
  command -v sudo >/dev/null 2>&1 || return 1

  # verifypw=all, sudo -n -v passes only with cached credentials or NOPASSWD on every rule
  if ! sudo -n -v >/dev/null 2>&1 </dev/null; then
    # a wrong or impossible (no terminal) password prompt isn't asked again in this script
    [ "$sudo_refused" != true ] || return 1
    if ! sudo -v </dev/null; then
      sudo_refused=true
      return 1
    fi
  fi

  sudo -n -l -- "$@" >/dev/null 2>&1 </dev/null
}

# Runs a command as root, directly when already root and through sudo otherwise.
#
# Arguments:
#   $@  Command and its arguments, an executable and not a shell function.
#
# Returns:
#   1 when sudo_allowed refuses the command, the command's status otherwise.
sudo_run() {
  sudo_allowed "$@" || return 1

  if [ "$(id -u)" -eq 0 ]; then
    "$@"
  else
    sudo -- "$@"
  fi
}

# Writes content and a trailing newline to a root-owned file.
#
# Arguments:
#   $1  File to write.
#   $2  Content to write.
#
# Returns:
#   1 when sudo_allowed refuses tee on that file, the write's status otherwise.
sudo_write() {
  # checked before the pipe, whose subshell would lose the refused state
  sudo_allowed tee "$1" || return 1
  printf '%s\n' "$2" | sudo_run tee "$1" >/dev/null
}
